<script setup lang="ts">
import {ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {catalogApi,bookingApi} from '@/api';import {auth} from '@/stores/auth';import type {Lesson,Equipment,Instructor,Slot} from '@/types';
const route=useRoute(),router=useRouter();const item=ref<Lesson|Equipment|null>(null),instructors=ref<Instructor[]>([]),slots=ref<Slot[]>([]),instructorId=ref(0),date=ref(''),start=ref(''),end=ref(''),size=ref(''),quantity=ref(1),error=ref(''),message=ref(''),loading=ref(false);const rental=ref(route.query.type==='rental');
async function init(){const id=Number(route.query.id);if(!id){error.value='Выберите услугу в каталоге';return}try{item.value=rental.value?await catalogApi.equipmentItem(id):await catalogApi.lesson(id);if(rental.value){size.value=(item.value as Equipment).sizes?.[0]||''}else{instructors.value=await catalogApi.instructors(id);instructorId.value=instructors.value[0]?.id||0}}catch(e){error.value='Не удалось загрузить'}}
async function loadSlots(){if(!date.value||!instructorId.value||rental.value)return;loading.value=true;slots.value=[];start.value='';try{slots.value=await catalogApi.slots(instructorId.value,date.value,Number(route.query.id))}catch(e){error.value='Не удалось загрузить'}finally{loading.value=false}}
watch([date,instructorId],loadSlots);init();
async function submit(){if(!auth.user){router.push({path:'/login',query:{next:route.fullPath}});return}error.value='';message.value='';loading.value=true;try{if(rental.value){if(!start.value||!end.value||!size.value)throw new Error('Заполните период аренды и размер');await bookingApi.createRental({equipmentId:Number(route.query.id),size:size.value,quantity:quantity.value,start:start.value,end:end.value})}else{if(!start.value)throw new Error('Выберите свободное время');await bookingApi.createLesson({lessonId:Number(route.query.id),instructorId:instructorId.value,start:start.value})}message.value='Бронирование создано';router.push('/account')}catch(e){error.value='Не удалось загрузить'}finally{loading.value=false}}
</script><template><div class="container section section--top"><h1 class="h1">Оформление бронирования</h1><p class="lead">Свободное время и возможность бронирования проверяет backend.</p><div class="card panel booking-form"><h2 class="h3">{{item?.title||'Выбор услуги'}}</h2><form class="form-stack" @submit.prevent="submit"><template v-if="!rental"><label>Инструктор<select v-model.number="instructorId" class="field" required><option v-for="i in instructors" :key="i.id" :value="i.id">{{i.name}}</option></select></label><label>Дата занятия<input v-model="date" type="date" class="field" required/></label><p v-if="loading">Загружаем свободные интервалы...</p><div v-if="slots.length" class="filters"><button v-for="slot in slots" :key="slot.start" type="button" class="filter-pill" :class="{'filter-pill--active':start===slot.start}" @click="start=slot.start">{{new Date(slot.start).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}}</button></div><p v-else-if="date&&!loading" class="muted">Свободных интервалов пока нет или сервер недоступен.</p></template><template v-else><label>Размер<select v-model="size" class="field" required><option v-for="s in (item as Equipment)?.sizes||[]" :key="s">{{s}}</option></select></label><label>Количество<input v-model.number="quantity" class="field" type="number" min="1" required/></label><label>Начало аренды<input v-model="start" class="field" type="datetime-local" required/></label><label>Конец аренды<input v-model="end" class="field" type="datetime-local" required/></label></template><p v-if="error" class="state-error">{{error}}</p><p v-if="message">{{message}}</p><button class="btn btn--primary" :disabled="loading">Забронировать</button></form></div></div></template>
